namespace Mdu.Service;

/// <summary>
/// The output folder <c>_mdu</c> holds navigation, scripts and styles generated by mdu. Site pages and assets
/// must not be written into it, but a source folder of that name is fine when nothing lands there.
/// </summary>
internal static class ReservedOutput
{
    internal const string Folder = "_mdu";

    private static readonly StringComparison PathComparison = OperatingSystem.IsWindows() || OperatingSystem.IsMacOS()
        ? StringComparison.OrdinalIgnoreCase
        : StringComparison.Ordinal;

    internal static bool Contains(string outputRoot, string path) =>
        Path.GetFullPath(path).StartsWith(
            Path.GetFullPath(Path.Combine(outputRoot, Folder)) + Path.DirectorySeparatorChar, PathComparison);

    internal static InvalidOperationException Collision(string outputRoot, string path) => new(
        $"'{Path.GetRelativePath(outputRoot, path)}' would be written into the '{Folder}' output folder, " +
        "which is reserved for files generated by mdu. Rename or move it in the documentation.");
}
